"use client";
import React, { useEffect, useState } from "react";
import { useSearchParams } from "next/navigation";
import axios from "axios";
import dynamic from "next/dynamic";
import VideoPlayer from "../components/videoplayer";

const ReactPlayer = dynamic(() => import("react-player"), { ssr: false });

const WatchPage = () => {
  const searchParams = useSearchParams();
  const id = searchParams.get("id"); // video ID from query
  const [video, setVideo] = useState(null);

  useEffect(() => {
    const fetchVideo = async () => {
      try {
        const res = await axios.get("http://localhost:8082/watch"); // all videos
        const allVideos = res.data;
        const found = allVideos.find(
          (v) => v.id === id || v._source?._id === id
        );
        setVideo(found);
      } catch (error) {
        console.log("Error fetching videos:", error);
      }
    };
    fetchVideo();
  }, [id]);

  if (!video) return <div className="p-10">Loading video...</div>;

  return (
    <div className="p-10">
      <h1 className="text-2xl font-bold mb-4">
        {video.title || video._source?.title}
      </h1>
      <div className="mb-4">
        {video.transcodedUrl ? (
          <VideoPlayer transcodedUrl={video.transcodedUrl} />
        ) : (
          <ReactPlayer
            url={video.url}
            controls
            width="720px"
            height="400px"
          />
        )}
      </div>
      <p className="text-gray-700">{video.description || video._source?.description}</p>
      <p className="text-gray-700">Author: {video.author || video._source?.author}</p>
    </div>
  );
};

export default WatchPage;

